
(function() {
  const frame = document.getElementById('cyberShieldFrame');
  const cards = document.querySelectorAll('[data-gamepanel="cyber"]');
  if (!frame) return;
  const source64 = '';
  let initialized = false;
  function loadCyberShield() {
    if (initialized) return;
    initialized = true;
    try {
      const bytes = Uint8Array.from(atob(source64), ch => ch.charCodeAt(0));
      frame.srcdoc = new TextDecoder('utf-8').decode(bytes);
    } catch (err) {
      frame.srcdoc = `<!doctype html><html lang="id"><meta charset="utf-8"><body style="font:16px system-ui;background:#05060d;color:#fff;padding:24px">CyberShield gagal dimuat. Muat ulang halaman NEXORA.
<style id="nexora-logo-integration">
.auth-mark .nexora-logo-symbol{width:48px;height:48px;object-fit:contain;filter:drop-shadow(0 0 10px rgba(50,210,255,.2))}
.auth-mark b{display:none}
.logo .nexora-logo-box{display:grid;place-items:center;width:38px;height:38px;padding:3px;border-radius:11px;background:linear-gradient(145deg,#13263d,#17162f)!important;border:1px solid rgba(91,211,255,.25);box-shadow:0 0 18px rgba(50,210,255,.12)!important;animation:none!important}
.logo .nexora-logo-box img{width:100%;height:100%;object-fit:contain}
.nav-brand-mark{display:grid;place-items:center;overflow:hidden;padding:3px;background:linear-gradient(145deg,#13263d,#17162f)!important;border:1px solid rgba(91,211,255,.25);box-shadow:0 0 18px rgba(50,210,255,.12)!important}
.nav-brand-mark img{width:100%;height:100%;object-fit:contain}
@media(max-width:760px){.logo .nexora-logo-box{width:30px;height:30px;padding:2px}.nav-brand-mark{width:39px;height:39px}}
</style>


<style id="nexora-answer-review-style">
.nq-answer-review{margin-top:14px;padding:12px 14px;border:1px solid var(--stroke);border-radius:13px;background:rgba(255,255,255,.035)}
.nq-answer-review summary{cursor:pointer;font-weight:700;color:var(--c1)}
.nq-answer-review ol{padding-left:22px;margin-top:10px}.nq-answer-review li{padding:8px 0;color:var(--mut);font-size:12px;line-height:1.7}
</style>
</body></html>`;
    }
  }
  cards.forEach(card => card.addEventListener('click', loadCyberShield));
  window.addEventListener('message', function(event) {
    if (event.source !== frame.contentWindow || !event.data || typeof event.data !== 'object') return;
    if (event.data.type === 'netquest-cyber-height') {
      const height = Number(event.data.height);
      if (Number.isFinite(height)) frame.style.height = Math.max(1150, Math.min(4800, height + 24)) + 'px';
    }
    if (event.data.type === 'netquest-cyber-request-history') {
      let history = [];
      try {
        const saved = JSON.parse(localStorage.getItem('cybershield_v8_hist') || '[]');
        if (Array.isArray(saved)) history = saved.slice(0, 100);
      } catch (e) {}
      frame.contentWindow.postMessage({ type: 'netquest-cyber-history', history }, '*');
    }
    if (event.data.type === 'netquest-cyber-save-history') {
      if (Array.isArray(event.data.history)) {
        try { localStorage.setItem('cybershield_v8_hist', JSON.stringify(event.data.history.slice(0, 100))); } catch (e) {}
      }
    }
    if (event.data.type === 'netquest-cyber-completed') {
      if (typeof window.netquestAwardCyberShield === 'function' && window.netquestAwardCyberShield()) {
        const reward = document.getElementById('cyberQuestReward');
        if (reward) reward.textContent = '✓ Pemindaian pertama selesai. Kamu memperoleh +25 XP! Tantangan ini hanya memberi XP satu kali per akun.';
      }
    }
  });
})();
